// WARDEN-W2 Node 1: Token Verification
const query = $input.first().json.query;

// Verify WARDEN_RESOLVE_TOKEN
if (!query.token || query.token !== $env.WARDEN_RESOLVE_TOKEN) {
  return [{
    json: {
      error_response: true,
      status_code: 403,
      response_body: { error: 'Forbidden' },
      query: query
    }
  }];
}

// Validate action
if (!query.action || (query.action !== 'approve' && query.action !== 'deny')) {
  return [{
    json: {
      error_response: true,
      status_code: 400,
      response_body: { error: 'Invalid action parameter' },
      query: query
    }
  }];
}

// Validate id
if (!query.id) {
  return [{
    json: {
      error_response: true,
      status_code: 400,
      response_body: { error: 'Missing transaction ID' },
      query: query
    }
  }];
}

return [{
  json: {
    error_response: false,
    transaction_id: query.id,
    action: query.action,
    query: query
  }
}];

// WARDEN-W2 Node 2: State Check - Replay Attack Prevention
const data = $input.first().json;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY;

// Query Supabase for the transaction
const res = await fetch(
  `${supabaseUrl}/rest/v1/warden_transactions?id=eq.${data.transaction_id}&select=id,status,requesting_agent,target_service,payload_data,security_hash`,
  {
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json'
    }
  }
);
const rows = await res.json();

// Row not found
if (!rows || rows.length === 0) {
  return [{
    json: {
      error_response: true,
      status_code: 404,
      response_body: { error: 'Transaction not found' },
      action: data.action,
      transaction_id: data.transaction_id
    }
  }];
}

const row = rows[0];

// Replay attack prevention: status must be PENDING
if (row.status !== 'PENDING') {
  return [{
    json: {
      error_response: true,
      status_code: 409,
      response_body: { error: 'Transaction already resolved', current_status: row.status },
      action: data.action,
      transaction_id: data.transaction_id
    }
  }];
}

// Pass row data forward
return [{
  json: {
    error_response: false,
    transaction_id: row.id,
    action: data.action,
    requesting_agent: row.requesting_agent,
    target_service: row.target_service,
    payload_data: row.payload_data,
    security_hash: row.security_hash
  }
}];

// Combined Action Handler: Approve/Deny branching
const data = $input.first().json;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY;
const timestamp = new Date().toISOString();

if (data.action === 'deny') {
  // DENY: Update status and return deny HTML
  await fetch(
    `${supabaseUrl}/rest/v1/warden_transactions?id=eq.${data.transaction_id}`,
    {
      method: 'PATCH',
      headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'DENIED', resolution_notes: `Denied by administrator at ${timestamp}` })
    }
  );

  // Resume W1 (best-effort)
  const n8nBaseUrl = $env.N8N_BASE_URL;
  try {
    await fetch(`${n8nBaseUrl}/webhook/warden/resume/${data.transaction_id}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'DENIED', resolution_notes: `Denied by administrator at ${timestamp}` })
    });
  } catch(e) {}

  const html = `<html><body style="font-family:Arial,sans-serif;text-align:center;padding:50px;">
<h1 style="color:#dc3545;">Request Denied</h1>
<p>Transaction ID: ${data.transaction_id}</p>
<p>The credential request has been denied and logged.</p>
</body></html>`;

  return [{ json: { is_deny: true, response_html: html, transaction_id: data.transaction_id } }];
}

// APPROVE: Update status to APPROVED, then continue to Service Router
await fetch(
  `${supabaseUrl}/rest/v1/warden_transactions?id=eq.${data.transaction_id}`,
  {
    method: 'PATCH',
    headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ status: 'APPROVED' })
  }
);

return [{ json: { ...data, is_deny: false, status: 'APPROVED' } }];

// Service Router - routes to correct API based on target_service
const data = $input.first().json;
const target = data.target_service;
const payload = data.payload_data;
let api_response = null;
let api_error = null;

try {
  if (target === 'Generic') {
    const res = await fetch(payload.url, {
      method: payload.method || 'POST',
      headers: { 'Content-Type': 'application/json', ...(payload.headers || {}) },
      body: payload.method === 'GET' ? undefined : JSON.stringify(payload.body || {})
    });
    api_response = { status: res.status, body: await res.text() };
  } else if (target === 'Twilio') {
    // Would use Twilio credentials - placeholder for now
    api_response = { status: 200, body: 'Twilio call simulated (no credentials configured)' };
  } else if (target === 'Google_Sheets') {
    api_response = { status: 200, body: 'Google Sheets operation simulated' };
  } else if (target === 'Stripe') {
    api_response = { status: 200, body: 'Stripe operation simulated' };
  } else if (target === 'GitHub') {
    api_response = { status: 200, body: 'GitHub operation simulated' };
  } else if (target === 'Supabase_Direct') {
    const supabaseUrl = $env.SUPABASE_URL;
    const supabaseKey = $env.SUPABASE_SERVICE_KEY;
    const res = await fetch(`${supabaseUrl}/rest/v1/${payload.table}`, {
      method: payload.method || 'POST',
      headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload.body || {})
    });
    api_response = { status: res.status, body: await res.text() };
  } else if (target === 'ManyChat') {
    api_response = { status: 200, body: 'ManyChat operation simulated' };
  } else {
    throw new Error(`Unknown target_service: ${target}`);
  }
} catch (e) {
  api_error = e.message;
}

return [{ json: { ...data, api_response, api_error, execution_success: !api_error } }];

// WARDEN-W2 Node 5: Final Reconciliation
const data = $input.first().json;
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY;
const n8nBaseUrl = $env.N8N_BASE_URL;
const timestamp = new Date().toISOString();

const transaction_id = data.transaction_id;
const target_service = data.target_service;

let final_status = 'EXECUTED';
let resolution_notes = '';

if (data.api_error || !data.execution_success) {
  final_status = 'FAILED';
  resolution_notes = `API Error: ${data.api_error || 'Unknown error'}. Timestamp: ${timestamp}`;
} else {
  const responseStr = typeof data.api_response === 'string' 
    ? data.api_response.slice(0, 500) 
    : JSON.stringify(data.api_response).slice(0, 500);
  resolution_notes = `Executed at ${timestamp}. Response: ${responseStr}`;
}

// Update Supabase
await fetch(
  `${supabaseUrl}/rest/v1/warden_transactions?id=eq.${transaction_id}`,
  {
    method: 'PATCH',
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ status: final_status, resolution_notes })
  }
);

// Resume Workflow 1 (best-effort)
try {
  await fetch(`${n8nBaseUrl}/webhook/warden/resume/${transaction_id}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status: final_status, resolution_notes, api_response: data.api_response })
  });
} catch (e) {}

// Return HTML response for Sheridan's browser
const html = `<html><body style="font-family:Arial,sans-serif;text-align:center;padding:50px;">
<h1 style="color:#28a745;">Approved</h1>
<p>Executing <strong>${target_service}</strong> request.</p>
<p>Transaction ${transaction_id} — check your Warden log for results.</p>
<p>Status: ${final_status}</p>
</body></html>`;

return [{ json: { 
  transaction_id, final_status, resolution_notes,
  response_html: html
} }];

